x = -1:0.05:1;
y = -1:0.05:1;

[X,Y] = meshgrid(x,y);

Z = 1 - (X.^2 + Y.^2);

figure; %[output:2b64f4c5]
surf(X,Y,Z,'FaceColor','blue','EdgeColor','none'); %[output:2b64f4c5]

alpha(0.5); %[output:2b64f4c5]

xlabel('x'); %[output:2b64f4c5]
ylabel('y'); %[output:2b64f4c5]
zlabel('z'); %[output:2b64f4c5]

title('z(x,y) = 1 - (x^2 + y^2)'); %[output:2b64f4c5]

grid on; %[output:2b64f4c5]

